const candidates = $input.first().json.candidates || [];

return [
  {
    json: {
      subject: `🚨 Daily Risk Alert: ${candidates.length} High Risk Candidates Detected`,
      message:
        `<h3>Daily Candidate Risk Scan Results</h3>` +
        `<p>Found <b>${candidates.length}</b> high-risk candidates requiring review:</p><ul>` +
        candidates
          .map(
            (c) =>
              `<li><b>${c.name}</b> (${c.position}): Fit Score ${c.fit_score.toFixed(1)} - ${c.fit_category} [${c.alert_reason}]</li>`
          )
          .join("") + "</ul>",
    },
  },
];
